patch:
diff --git a/tests/repro/no-unused-expressions-use-strict.js b/tests/repro/no-unused-expressions-use-strict.js
new file mode 100644
index 0000000..b91b35a
--- /dev/null
+++ b/tests/repro/no-unused-expressions-use-strict.js
@@ -0,0 +1,15 @@
+"use strict";
+const { Linter } = require(process.argv[2] || "../../lib/api");
+const pkg = require((process.argv[2] ? process.argv[2] + "/../../" : "../../") + "package.json");
+const linter = new Linter();
+const code = "'use strict';\nfunction f() { 'use strict'; }\n";
+let failed = false;
+for (const ecmaVersion of [3, 5, 2015, "latest"]) {
+	const messages = linter.verify(code, {
+		languageOptions: { ecmaVersion, sourceType: "script" },
+		rules: { "no-unused-expressions": "error" },
+	});
+	if (messages.length) failed = true;
+	console.log(`eslint ${pkg.version} ecmaVersion=${ecmaVersion}:`, messages.length ? messages.map(m => `${m.line}:${m.column} ${m.message}`).join(" | ") : "no errors");
+}
+process.exitCode = failed ? 1 : 0;
